sed -n 90,105p src/components/dashboard/RecentRuns.tsx; sed -n 355,372p src/pages/Results.tsx; sed -n 338,352p src/pages/Assets.tsx; echo ---; python3 - <<'EOF'
def lum(h):
    h=h.lstrip('#'); c=[int(h[i:i+2],16)/255 for i in (0,2,4)]
    c=[x/12.92 if x<=0.03928 else ((x+0.055)/1.055)**2.4 for x in c]
    return 0.2126*c[0]+0.7152*c[1]+0.0722*c[2]
def cr(a,b):
    la,lb=sorted([lum(a),lum(b)],reverse=True); return (la+0.05)/(lb+0.05)
def blend(alpha,bg,fg=(0,0,0)):
    b=[int(bg.lstrip('#')[i:i+2],16) for i in (0,2,4)]
    return '#%02x%02x%02x'%tuple(round(fg[i]*alpha+b[i]*(1-alpha)) for i in range(3))
for bg in ('#ffffff','#f4f5f7'):
    for a in (0.45,0.55,0.6,0.65):
        print(bg,a,round(cr(blend(a,bg),bg),2))
for fg,bg,n in (('#52c41a','#f6ffed','tag-success'),('#389e0d','#f6ffed','green-7'),('#ff4d4f','#fff2f0','tag-error'),('#cf1322','#fff2f0','red-7'),('#d48806','#fffbe6','gold-7'),('#8c8c8c','#ffffff','muted')):
    print(n,round(cr(fg,bg),2))
EOF

