    await expect(page.getByTestId('rd-screen')).toBeVisible();
    const snap = async (tag: string) => {
      const r = await new AxeBuilder({ page }).analyze();
      const n = r.violations.filter(v => ['serious','critical'].includes(v.impact ?? '')).reduce((a, v) => a + v.nodes.length, 0);
      console.log(tag, page.url().slice(-12), 'rows', await page.locator('tr.ant-table-row').count(), 'secondary', await page.locator('.ant-typography-secondary').count(), 'violNodes', n);
    };
    await snap('t0'); await page.waitForTimeout(1500); await snap('t1.5s');
  });
}
EOF
