input.command:
cat > e2e/zz-debug.spec.ts <<'EOF'
import AxeBuilder from '@axe-core/playwright';
import { expect, test } from '@playwright/test';
for (const mode of ['light', 'dark']) test(`probe ${mode}`, async ({ page }) => {
  await page.addInitScript((m) => localStorage.setItem('dq-theme-mode', m), mode);
  const out: string[] = [];
  for (const url of ['/dashboard', '/connections', '/suites', '/results', '/assets', '/admin']) {
    await page.goto(url);
    await expect(page.locator('.ant-spin-spinning, .ant-skeleton-active')).toHaveCount(0);
    await page.waitForTimeout(600);
    const r = await new AxeBuilder({ page }).analyze();
    const by: Record<string, number> = {};
    for (const v of r.violations) if (['serious', 'critical'].includes(v.impact ?? '')) by[v.id] = (by[v.id] ?? 0) + v.nodes.length;
    out.push(`${url} ${JSON.stringify(by)}`);
    if (mode === 'dark' || url === '/dashboard') for (const v of r.violations.filter(v => v.id === 'color-contrast')) for (const n of v.nodes.slice(0, 4)) out.push('   ' + String(n.target).slice(-70) + ' :: ' + (n.any[0]?.message ?? '').slice(0, 110));
  }
  console.log(`MODE ${mode} theme=${await page.evaluate(() => document.documentElement.dataset.theme)}\n` + out.join('\n'));
});
EOF
