import { expect, test } from '@playwright/test';
import { settle } from '../scripts/a11y/settle';
test('probe dark solids', async ({ page }) => {
  await page.addInitScript(() => localStorage.setItem('dq-theme-mode', 'dark'));
  await page.goto('/results'); await settle(page);
  const col = (sel: string) => page.evaluate((s) => { const e = document.querySelector(s)!; const c = getComputedStyle(e); let b: Element | null = e; let bg = 'rgba(0, 0, 0, 0)'; while (b && bg === 'rgba(0, 0, 0, 0)') { bg = getComputedStyle(b).backgroundColor; b = b.parentElement; } return `${c.color} on ${bg}`; }, sel);
  console.log('BTN', await col('.ant-btn-primary span:last-child'));
  console.log('AVATAR', await col('.ant-avatar-string'));
  const candidates = page.locator('[aria-describedby], .ant-typography-ellipsis, td .ant-tag');
  await page.locator('td .ant-tag').first().hover(); await page.waitForTimeout(600);
  let n = await page.locator('.ant-tooltip-container, .ant-tooltip-inner').count();
  if (!n) { await page.goto('/connections'); await settle(page); for (const b of await page.locator('button, .anticon').all()) { await b.hover().catch(() => {}); await page.waitForTimeout(250); if (await page.locator('.ant-tooltip-container, .ant-tooltip-inner').count()) break; } }
  n = await page.locator('.ant-tooltip-container, .ant-tooltip-inner').count();
  console.log('TOOLTIPS', n, n ? await col('.ant-tooltip-container, .ant-tooltip-inner') : '');
  void candidates; void expect;
});
EOF
