cat > e2e/zz-debug.spec.ts <<'EOF'
import AxeBuilder from '@axe-core/playwright';
import { expect, test } from '@playwright/test';
import { settle } from '../scripts/a11y/settle';
test('probe dark all', async ({ page }) => {
  await page.addInitScript(() => localStorage.setItem('dq-theme-mode', 'dark'));
  let total = 0;
  const scan = async () => { await settle(page); const r = await new AxeBuilder({ page }).withRules(['color-contrast']).analyze(); total += r.violations.reduce((a, v) => a + v.nodes.length, 0); };
  for (const u of ['/dashboard', '/connections', '/suites', '/results', '/assets', '/admin']) { await page.goto(u); await page.waitForTimeout(400); await scan(); }
  await page.goto('/suites'); await page.getByText('Orders quality').click();
  await expect(page.getByRole('heading', { name: 'Orders quality', level: 4 })).toBeVisible(); await scan();
  await page.goto('/results'); await page.locator('tr.ant-table-row').first().click();
  await expect(page.getByTestId('rd-screen')).toBeVisible(); await scan();
  console.log('DARK contrast violations, 8 surfaces:', total);
});
EOF
E2E_BASE_URL=http://127.0.0.1:3001 pnpm exec playwright test e2e/zz-debug.spec.ts e2e/a11y.spec.ts --project=chromium --workers=1 --reporter=line 2>&1 | grep -E "^DARK|passed|failed"; rm e2e/zz-debug.spec.ts; pnpm exec eslint src/theme.ts && pnpm exec vitest run 2>&1 | grep -E "Tests |FAIL"; git status --short

